function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = grid.length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square: every row needs n cells.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

