function minSwaps(grid) {
  const n = grid.length;
  const lastOne = [];
  for (const row of grid) {
    let col = n - 1;
    while (col >= 0 && row[col] === 0) {
      col--;
    }
    lastOne.push(col);
  }

  let swaps = 0;
  for (let target = 0; target < n; target++) {
    let pick = target;
    while (pick < n && lastOne[pick] > target) {
      pick++;
    }
    if (pick === n) {
      return -1;
    }
    swaps += pick - target;
    const moved = lastOne.splice(pick, 1)[0];
    lastOne.splice(target, 0, moved);
  }
  return swaps;
}

