function minSwaps(grid) {
  // Breadth-first search over row orders; each edge is one adjacent swap.
  const n = grid.length;
  const valid = order => order.every((r, i) => grid[r].every((v, j) => j <= i || v === 0));
  const start = Array.from({ length: n }, (_, i) => i);
  const seen = new Set([start.join(',')]);
  let frontier = [start];
  for (let steps = 0; frontier.length; steps++) {
    const next = [];
    for (const order of frontier) {
      if (valid(order)) return steps;
      for (let i = 0; i + 1 < n; i++) {
        const copy = order.slice();
        [copy[i], copy[i + 1]] = [copy[i + 1], copy[i]];
        const key = copy.join(',');
        if (!seen.has(key)) { seen.add(key); next.push(copy); }
      }
    }
    frontier = next;
  }
  return -1;
}

