function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const pick = k => Math.floor(rand() * k);
  if (size === 'small' && rand() < 0.25) {
    // Fully random cells.
    const density = rand();
    return [Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
  }
  // Give each row a planned rightmost 1 at most its slot in a hidden valid order,
  // then sometimes loosen one row so the grid may become impossible.
  const slots = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [slots[i], slots[j]] = [slots[j], slots[i]];
  }
  const breakIt = rand() < (size === 'large' ? 0.15 : 0.3);
  const grid = slots.map(slot => {
    let last = slot - pick(Math.min(slot + 2, 3));
    if (breakIt && rand() < 0.3) last = n - 1;
    const row = Array.from({ length: n }, (_, j) => (j < last && rand() < 0.5 ? 1 : 0));
    if (last >= 0) row[last] = 1;
    return row;
  });
  return [grid];
}
